//go:build atdd_redphase

// ATDD red-phase scaffold for Story 1.4 — genlib package: Generate unique
// code-emission path (plan.Validate → emit). This is the second of two test
// files; the first is plan/registry_test.go (Validate assertions).
//
// AC1: legal graph → compilable container with "Code generated by" header.
// AC2: bad graph (missing dep) → error + nil output (zero-byte code).
// AC3: pipeline one-way dependency (plan ← genlib, no reverse).
// AC4: golden test + format.Source + go/types type-check.
//
// Activation (TDD red -> green): delete the //go:build line above and the blank
// line after it once genlib.Generate exists (Story 1.4 Task 3). The file then
// joins the default build and these assertions drive the slice to green.
// See _bmad-output/test-artifacts/atdd-checklist-1-4-codegen-validate-gate.md.
//
// API CONTRACT THIS SCAFFOLD ASSUMES (D2 recommended):
//
//	genlib.Generate(reg *plan.Registry, pkgName string) ([]byte, error)
//
// If the dev pins a different signature (e.g., pkgName on Registry), update the
// calls below — the BEHAVIORS asserted (compilable output, bad-graph rejection,
// golden stability, type-check, dependency direction) are the contract and must
// not change.
package genlib_test

import (
	"go/ast"
	"go/format"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"os"
	"os/exec"
	"strings"
	"testing"

	"github.com/gonewx/godi/internal/genlib"
	"github.com/gonewx/godi/internal/testutil"
	"github.com/gonewx/godi/plan"
)

// singleServiceRegistry returns a Registry with one no-dep singleton — the
// canonical minimum-viable registration for Generate.
func singleServiceRegistry() *plan.Registry {
	reg := plan.NewRegistry()
	reg.Service(plan.Service{
		Name:     "Logger",
		GoType:   "*logger.Logger",
		Ctor:     "logger.NewLogger",
		Lifetime: plan.Singleton,
	})
	return reg
}

// --- 1.4-GEN-001 (AC1/AC4, P0) ------------------------------------------------

// TestGenerate_LegalGraph_ProducesFormattedCode: a legal single-service graph
// passes through the unique code-emission path genlib.Generate (AD-2) and
// produces gofmt-legal code (format.Source succeeds). The output must be
// non-empty.
func TestGenerate_LegalGraph_ProducesFormattedCode(t *testing.T) {
	reg := singleServiceRegistry()
	src, err := genlib.Generate(reg, "container")
	testutil.NoError(t, err)
	testutil.True(t, len(src) > 0, "legal graph must produce non-empty code")

	_, fmtErr := format.Source(src)
	testutil.NoError(t, fmtErr)
}

// --- 1.4-GEN-002 (AC1, P0) ----------------------------------------------------

// TestGenerate_LegalGraph_GeneratedCodeHeader: the generated file's first line
// must be the canonical "Code generated by" marker per Consistency Conventions.
func TestGenerate_LegalGraph_GeneratedCodeHeader(t *testing.T) {
	reg := singleServiceRegistry()
	src, err := genlib.Generate(reg, "container")
	testutil.NoError(t, err)

	firstLine := strings.SplitN(string(src), "\n", 2)[0]
	testutil.True(t, strings.HasPrefix(firstLine, "// Code generated by"),
		"first line must be '// Code generated by ...; DO NOT EDIT.'")
}

// --- 1.4-GEN-003 (AC4, P0) ----------------------------------------------------

// TestGenerate_LegalGraph_GoldenTest: the output for the canonical single-service
// registration is byte-stable across runs — anchored by a committed golden file.
// First run with -update-golden to create testdata/single-service.golden.
// AD-15: golden code-emission test is the starting point for B2 equivalence
// evidence.
func TestGenerate_LegalGraph_GoldenTest(t *testing.T) {
	reg := singleServiceRegistry()
	src, err := genlib.Generate(reg, "container")
	testutil.NoError(t, err)
	testutil.Golden(t, "single-service", src)
}

// --- 1.4-GEN-004 (AC2, P0) ----------------------------------------------------

// TestGenerate_MissingDep_ReturnsErrorAndNilCode: a bad graph (service depends
// on an unregistered type) is rejected: Generate returns error and nil output
// (zero-byte code). AD-3: bad graph → no code emitted. NFR2: hard gate.
func TestGenerate_MissingDep_ReturnsErrorAndNilCode(t *testing.T) {
	reg := plan.NewRegistry()
	reg.Service(plan.Service{
		Name:     "Handler",
		GoType:   "*http.Handler",
		Ctor:     "NewHandler",
		Lifetime: plan.Singleton,
		Deps:     []string{"Logger"},
	})

	src, err := genlib.Generate(reg, "container")
	testutil.Error(t, err)
	testutil.Nil(t, src)
	testutil.True(t, strings.Contains(err.Error(), "missing dependency") ||
		strings.Contains(err.Error(), "unregistered"),
		"error must describe the missing dependency")
}

// --- 1.4-GEN-005 (AC4, P1) ----------------------------------------------------

// TestGenerate_EmptyGraph_ProducesLegalCode: an empty Registry produces legal
// (possibly minimal) code — an empty container is not an error.
func TestGenerate_EmptyGraph_ProducesLegalCode(t *testing.T) {
	reg := plan.NewRegistry()
	src, err := genlib.Generate(reg, "container")
	testutil.NoError(t, err)
	testutil.True(t, len(src) > 0, "empty graph must still produce a valid package declaration")

	_, fmtErr := format.Source(src)
	testutil.NoError(t, fmtErr)
}

// --- 1.4-GEN-006 (AC1/AC4, P1) ------------------------------------------------

// TestGenerate_LegalGraph_TypeCheckable: the generated code passes go/types
// type-checking — semantic correctness beyond format.Source syntax check. This
// double-verifies AC1's "compilable" requirement. Uses importer.Default() to
// resolve imports (godi, reflect). If the dev chooses a minimal container that
// does not import external packages, importer.Default() suffices trivially.
func TestGenerate_LegalGraph_TypeCheckable(t *testing.T) {
	reg := singleServiceRegistry()
	src, err := genlib.Generate(reg, "container")
	testutil.NoError(t, err)

	fset := token.NewFileSet()
	f, parseErr := parser.ParseFile(fset, "container_gen.go", src, parser.AllErrors)
	testutil.NoError(t, parseErr)

	conf := types.Config{Importer: importer.Default()}
	_, typErr := conf.Check("container", fset, []*ast.File{f}, nil)
	testutil.NoError(t, typErr)
}

// --- 1.4-GEN-007 (AC3, P0) ----------------------------------------------------

// TestPipelineDependencyDirection: the generate pipeline follows AD-2's one-way
// dependency: cmd/godi-gen → internal/genlib → plan. Verified via `go list -deps`:
// plan must NOT import genlib or cmd; genlib must import plan and NOT import cmd.
func TestPipelineDependencyDirection(t *testing.T) {
	planDeps := goListDeps(t, "github.com/gonewx/godi/plan")
	for _, dep := range planDeps {
		testutil.True(t, !strings.Contains(dep, "genlib"),
			"plan must not import genlib (AD-2)")
		testutil.True(t, !strings.Contains(dep, "godi-gen"),
			"plan must not import cmd/godi-gen (AD-2)")
	}

	genlibDeps := goListDeps(t, "github.com/gonewx/godi/internal/genlib")
	hasPlan := false
	for _, dep := range genlibDeps {
		if strings.Contains(dep, "godi/plan") {
			hasPlan = true
		}
		testutil.True(t, !strings.Contains(dep, "godi-gen"),
			"genlib must not import cmd/godi-gen (AD-2)")
	}
	testutil.True(t, hasPlan, "genlib must depend on plan")
}

// goListDeps runs `GOWORK=off go list -deps <pkg>` and returns the dependency
// list. Fails the test on exec error.
func goListDeps(t *testing.T, pkg string) []string {
	t.Helper()
	cmd := exec.Command("go", "list", "-deps", pkg)
	env := make([]string, 0, len(os.Environ())+1)
	for _, e := range os.Environ() {
		if !strings.HasPrefix(e, "GOWORK=") {
			env = append(env, e)
		}
	}
	env = append(env, "GOWORK=off")
	cmd.Env = env
	out, err := cmd.Output()
	if err != nil {
		t.Fatalf("go list -deps %s: %v", pkg, err)
	}
	return strings.Split(strings.TrimSpace(string(out)), "\n")
}
